<?php
declare(strict_types=1);
session_start();
require __DIR__ . '/config.php';

function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function db(): PDO {
    static $pdo = null;
    if (!$pdo) $pdo = new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4', DB_USER, DB_PASS, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false
    ]);
    return $pdo;
}
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function verify_csrf(): void { if (!hash_equals(csrf(), $_POST['csrf'] ?? '')) { http_response_code(419); exit('Sesi tidak valid. Muat ulang halaman.'); } }
function user(): ?array { return $_SESSION['user'] ?? null; }
function require_login(): void { if (!user()) { header('Location: ?page=login'); exit; } }
function flash(string $s): void { $_SESSION['flash']=$s; }
function go(string $p='dashboard'): never { header('Location: ?page='.$p); exit; }

if (isset($_GET['logout'])) { session_destroy(); header('Location: ?page=login'); exit; }
$page = $_GET['page'] ?? 'dashboard';

if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    $action = $_POST['action'] ?? '';
    if ($action==='login') {
        $q=db()->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=? AND status="active" LIMIT 1');
        $q->execute([trim($_POST['email'] ?? '')]); $u=$q->fetch();
        if ($u && password_verify($_POST['password'] ?? '', $u['password_hash'])) {
            session_regenerate_id(true); $_SESSION['user']=$u; go();
        }
        flash('Email atau kata sandi tidak sesuai.'); go('login');
    }
    require_login();
    $role=user()['role'];
    if ($action==='save_patient' && $role==='admin') {
        $id=(int)($_POST['id'] ?? 0); $data=[trim($_POST['name']), (int)$_POST['age'], trim($_POST['gender']), trim($_POST['diagnosis']), trim($_POST['allergies']), trim($_POST['address']), trim($_POST['family_contact'])];
        if ($id) { $data[]=$id; db()->prepare('UPDATE patients SET name=?,age=?,gender=?,diagnosis=?,allergies=?,address=?,family_contact=? WHERE id=?')->execute($data); }
        else db()->prepare('INSERT INTO patients(name,age,gender,diagnosis,allergies,address,family_contact) VALUES(?,?,?,?,?,?,?)')->execute($data);
        flash('Data pasien berhasil disimpan.'); go('patients');
    }
    if ($action==='save_user' && $role==='admin') {
        $hash=password_hash($_POST['password'], PASSWORD_DEFAULT);
        db()->prepare('INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['email']),$hash,$_POST['role'],'active']);
        flash('Akun pengguna berhasil dibuat.'); go('users');
    }
    if ($action==='save_med' && in_array($role,['admin','nurse'],true)) {
        db()->prepare('INSERT INTO medications(patient_id,name,dose,scheduled_time,instructions,created_by) VALUES(?,?,?,?,?,?)')->execute([(int)$_POST['patient_id'],trim($_POST['name']),trim($_POST['dose']),$_POST['scheduled_time'],trim($_POST['instructions']),user()['id']]);
        flash('Jadwal obat ditambahkan.'); go('medications');
    }
    if ($action==='med_status' && in_array($role,['admin','nurse'],true)) {
        db()->prepare('UPDATE medications SET status=?,given_at=IF(?="given",NOW(),NULL),given_by=? WHERE id=?')->execute([$_POST['status'],$_POST['status'],user()['id'],(int)$_POST['id']]);
        go('medications');
    }
    if ($action==='save_visit' && in_array($role,['admin','nurse'],true)) {
        db()->prepare('INSERT INTO visits(patient_id,nurse_id,visit_at,notes) VALUES(?,?,?,?)')->execute([(int)$_POST['patient_id'],user()['id'],str_replace('T',' ',$_POST['visit_at']),trim($_POST['notes'])]);
        flash('Catatan kunjungan tersimpan.'); go('visits');
    }
    if ($action==='save_observation' && in_array($role,['admin','nurse'],true)) {
        db()->prepare('INSERT INTO observations(patient_id,recorded_by,blood_pressure,temperature,wound_size,complaint,notes) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['patient_id'],user()['id'],trim($_POST['blood_pressure']),$_POST['temperature'] ?: null,$_POST['wound_size'] ?: null,trim($_POST['complaint']),trim($_POST['notes'])]);
        flash('Pantauan kondisi tersimpan.'); go('observations');
    }
    if ($action==='save_message') {
        db()->prepare('INSERT INTO messages(patient_id,sender_id,message) VALUES(?,?,?)')->execute([(int)$_POST['patient_id'],user()['id'],trim($_POST['message'])]);
        flash('Pesan berhasil dikirim.'); go('messages');
    }
    if ($action==='save_report' && in_array($role,['admin','nurse'],true)) {
        db()->prepare('INSERT INTO reports(patient_id,author_id,report_date,summary,actions_taken,response) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE summary=VALUES(summary),actions_taken=VALUES(actions_taken),response=VALUES(response),author_id=VALUES(author_id)')->execute([(int)$_POST['patient_id'],user()['id'],$_POST['report_date'],trim($_POST['summary']),trim($_POST['actions_taken']),trim($_POST['response'])]);
        flash('Laporan harian tersimpan.'); go('reports');
    }
}
if ($page==='login') {
    ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masuk · RawatBersama</title><link rel="stylesheet" href="assets/style.css"></head><body class="login-body"><main class="login-card"><a class="brand" href="#"><span class="brand-mark">R+</span><span><b>RawatBersama</b><small>Care coordination platform</small></span></a><div class="login-heading"><span class="eyebrow">SELAMAT DATANG</span><h1>Masuk ke akun Anda</h1><p>Kelola informasi perawatan dalam satu tempat.</p></div><?php if(!empty($_SESSION['flash'])){echo '<div class="alert">'.e($_SESSION['flash']).'</div>';unset($_SESSION['flash']);} ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="login"><label>Email</label><input type="email" name="email" placeholder="nama@email.com" required><label>Kata sandi</label><input type="password" name="password" placeholder="Masukkan kata sandi" required><button class="btn btn-primary btn-wide">Masuk <span>→</span></button></form><p class="login-foot">Akses khusus keluarga, perawat, dan administrator.</p></main></body></html><?php exit;
}
require_login();
$me=user(); $role=$me['role']; $pdo=db();
$patients=$pdo->query('SELECT id,name,age,gender,diagnosis FROM patients ORDER BY name')->fetchAll();
$selected=(int)($_GET['patient_id'] ?? ($patients[0]['id'] ?? 0));
$patient=$selected ? ($pdo->prepare('SELECT * FROM patients WHERE id=?')) : null;
if($patient){$patient->execute([$selected]);$patient=$patient->fetch();}
$canManage=in_array($role,['admin','nurse'],true);
$allowed=['dashboard','patients','users','medications','visits','observations','messages','reports'];
if(!in_array($page,$allowed,true)) $page='dashboard';
function count_rows(string $sql): int { return (int)db()->query($sql)->fetchColumn(); }
$stats=['patients'=>count_rows('SELECT COUNT(*) FROM patients'),'nurses'=>count_rows("SELECT COUNT(*) FROM users WHERE role='nurse' AND status='active'"),'meds'=>count_rows("SELECT COUNT(*) FROM medications WHERE status='pending'"),'reports'=>count_rows('SELECT COUNT(*) FROM reports WHERE report_date=CURDATE()')];
$latestObs=$selected ? $pdo->prepare('SELECT * FROM observations WHERE patient_id=? ORDER BY recorded_at DESC LIMIT 1') : null;
if($latestObs){$latestObs->execute([$selected]);$latestObs=$latestObs->fetch();}
$flash=$_SESSION['flash'] ?? ''; unset($_SESSION['flash']);
$nav=[['dashboard','▦','Ringkasan'],['patients','♡','Data pasien'],['medications','◷','Jadwal obat'],['visits','＋','Kunjungan'],['observations','⌁','Pantauan kondisi'],['messages','✉','Pesan'],['reports','▤','Laporan']];
if($role==='admin') $nav[]=['users','♙','Manajemen pengguna'];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RawatBersama · <?=e(ucfirst($page))?></title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="?page=dashboard"><span class="brand-mark">R+</span><span><b>RawatBersama</b><small>CARE MANAGEMENT</small></span></a><div class="side-label">WORKSPACE</div><nav class="side-nav"><?php foreach($nav as [$key,$icon,$label]):?><a class="<?= $page===$key?'active':''?>" href="?page=<?=$key?>"><span class="nav-icon"><?=$icon?></span><?=$label?></a><?php endforeach;?></nav><div class="sidebar-bottom"><div class="help-card"><b>Butuh bantuan?</b><p>Hubungi administrator sistem untuk bantuan akses.</p></div><div class="user-mini"><div class="avatar"><?=e(strtoupper(substr($me['name'],0,1)))?></div><div><b><?=e($me['name'])?></b><small><?=e(ucfirst($role))?></small></div><a href="?logout=1" title="Keluar">↗</a></div></div></aside><div class="sidebar-backdrop" id="sidebarBackdrop" hidden></div><main class="main-area"><header class="topbar"><button type="button" class="mobile-menu" id="mobileMenu" aria-label="Buka menu navigasi" aria-controls="sidebar" aria-expanded="false">☰</button><div><span class="eyebrow">RAWATBERSAMA / <?=e(strtoupper($page))?></span><h2><?=e(['dashboard'=>'Ringkasan','patients'=>'Data pasien','users'=>'Manajemen pengguna','medications'=>'Jadwal obat','visits'=>'Kunjungan','observations'=>'Pantauan kondisi','messages'=>'Pesan','reports'=>'Laporan harian'][$page])?></h2></div><div class="top-actions"><span class="date-chip"><?=date('d M Y')?></span><div class="avatar avatar-small"><?=e(strtoupper(substr($me['name'],0,1)))?></div></div></header><section class="content"><?php if($flash):?><div class="alert success"><?=e($flash)?></div><?php endif;?>
<?php if($page==='dashboard'):?>
<div class="welcome-row"><div><span class="eyebrow">OVERVIEW</span><h1>Selamat datang, <?=e(explode(' ',$me['name'])[0])?> 👋</h1><p>Berikut ringkasan aktivitas perawatan hari ini.</p></div><?php if($patients):?><form method="get" class="patient-filter"><input type="hidden" name="page" value="dashboard"><label for="patient_id">Pilih pasien</label><select id="patient_id" name="patient_id" onchange="this.form.submit()"><?php foreach($patients as $p):?><option value="<?=$p['id']?>" <?=$selected===$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></form><?php endif;?></div>
<?php if($role==='admin'):?><div class="stat-grid"><article class="stat-card"><span>Total pasien</span><strong><?=$stats['patients']?></strong><small>Pasien terdaftar</small></article><article class="stat-card"><span>Perawat aktif</span><strong><?=$stats['nurses']?></strong><small>Pengguna perawat</small></article><article class="stat-card"><span>Obat menunggu</span><strong><?=$stats['meds']?></strong><small>Belum ditandai diberikan</small></article><article class="stat-card"><span>Laporan hari ini</span><strong><?=$stats['reports']?></strong><small>Laporan tersimpan</small></article></div><?php else:?><div class="stat-grid"><article class="stat-card"><span>Jadwal obat tertunda</span><strong><?=$stats['meds']?></strong><small>Seluruh pasien</small></article><article class="stat-card"><span>Pasien terdaftar</span><strong><?=$stats['patients']?></strong><small>Dalam sistem</small></article><article class="stat-card"><span>Laporan hari ini</span><strong><?=$stats['reports']?></strong><small>Laporan tersimpan</small></article></div><?php endif;?>
<?php if($patient):?><div class="section-title"><div><span class="eyebrow">PROFIL PASIEN</span><h3><?=e($patient['name'])?></h3><p><?=e($patient['age'])?> tahun · <?=e($patient['gender'])?> · <?=e($patient['diagnosis'] ?: 'Diagnosis belum diisi')?></p></div><a class="btn btn-outline" href="?page=patients">Lihat profil →</a></div><div class="two-col"><article class="panel-card"><div class="panel-head"><h3>Pantauan terakhir</h3><span class="tag">Kondisi</span></div><?php if($latestObs):?><div class="vital-grid"><div><small>Tekanan darah</small><b><?=e($latestObs['blood_pressure'] ?: '—')?></b><small>mmHg</small></div><div><small>Suhu tubuh</small><b><?=e($latestObs['temperature'] ?: '—')?>°</b><small>Celsius</small></div><div><small>Ukuran luka</small><b><?=e($latestObs['wound_size'] ?: '—')?></b><small>cm</small></div></div><p class="muted"><?=e($latestObs['complaint'] ?: 'Tidak ada keluhan tercatat')?></p><?php else:?><p class="empty">Belum ada data pemantauan untuk pasien ini.</p><?php endif;?></article><article class="panel-card"><div class="panel-head"><h3>Informasi penting</h3><span class="tag tag-warn">Perhatian</span></div><p><b>Alergi</b><br><?=e($patient['allergies'] ?: 'Belum dicatat')?></p><p><b>Alamat</b><br><?=e($patient['address'] ?: 'Belum dicatat')?></p><p><b>Kontak keluarga</b><br><?=e($patient['family_contact'] ?: 'Belum dicatat')?></p></article></div><?php else:?><div class="panel-card empty">Belum ada pasien. Administrator dapat menambahkan data pasien melalui menu Data pasien.</div><?php endif;?>
<div class="two-col"><article class="panel-card"><div class="panel-head"><h3>Aktivitas terbaru</h3><a href="?page=visits">Lihat semua</a></div><?php $acts=$pdo->query('SELECT v.visit_at,v.notes,u.name AS nurse,p.name AS patient FROM visits v JOIN users u ON u.id=v.nurse_id JOIN patients p ON p.id=v.patient_id ORDER BY v.visit_at DESC LIMIT 5')->fetchAll();foreach($acts as $a):?><div class="activity"><span class="activity-dot"></span><div><b><?=e($a['nurse'])?></b> · kunjungan <?=e($a['patient'])?><p><?=e($a['notes'])?></p><small><?=e($a['visit_at'])?></small></div></div><?php endforeach;?><?php if(!$acts):?><p class="empty">Belum ada aktivitas kunjungan.</p><?php endif;?></article><article class="panel-card"><div class="panel-head"><h3>Pengingat hari ini</h3><a href="?page=medications">Jadwal obat</a></div><?php $rem=$pdo->query("SELECT m.*,p.name patient FROM medications m JOIN patients p ON p.id=m.patient_id WHERE m.status='pending' ORDER BY m.scheduled_time LIMIT 5")->fetchAll();foreach($rem as $m):?><div class="reminder"><span class="time-pill"><?=e(substr($m['scheduled_time'],0,5))?></span><div><b><?=e($m['name'])?></b><small><?=e($m['patient'])?> · <?=e($m['dose'])?></small></div><span class="tag tag-warn">Menunggu</span></div><?php endforeach;?><?php if(!$rem):?><p class="empty">Tidak ada obat tertunda.</p><?php endif;?></article></div>
