<div class="page-intro"><div><h1>Data pasien</h1><p>Kelola profil dan informasi dasar pasien.</p></div><?php if($role==='admin'):?><button class="btn btn-primary" onclick="document.getElementById('patientForm').hidden=false">＋ Tambah pasien</button><?php endif;?></div>
<?php if($role==='admin'):?><form class="panel-card form-panel" id="patientForm" method="post" hidden><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_patient"><h3>Tambah pasien</h3><div class="form-grid"><label>Nama lengkap<input name="name" required></label><label>Usia<input type="number" min="0" max="120" name="age" required></label><label>Jenis kelamin<select name="gender"><option>Perempuan</option><option>Laki-laki</option></select></label><label>Diagnosis<input name="diagnosis"></label><label>Alergi<input name="allergies"></label><label>Kontak keluarga<input name="family_contact"></label><label class="span-2">Alamat<textarea name="address"></textarea></label></div><button class="btn btn-primary">Simpan pasien</button></form><?php endif;?><div class="panel-card table-card"><div class="table-wrap"><table><thead><tr><th>Nama pasien</th><th>Usia</th><th>Jenis kelamin</th><th>Diagnosis</th><th>Status</th></tr></thead><tbody><?php foreach($patients as $p):?><tr><td><b><?=e($p['name'])?></b><small>ID #<?=e($p['id'])?></small></td><td><?=e($p['age'])?> th</td><td><?=e($p['gender'])?></td><td><?=e($p['diagnosis'] ?: '—')?></td><td><span class="tag">Terdaftar</span></td></tr><?php endforeach;?></tbody></table></div><?php if(!$patients):?><p class="empty">Data pasien belum tersedia.</p><?php endif;?></div>
