<div class="page-intro"><div><h1>Pantauan kondisi</h1><p>Catat tanda vital, keluhan, dan perkembangan pasien.</p></div><?php if($canManage):?><button class="btn btn-primary" onclick="document.getElementById('obsForm').hidden=false">＋ Tambah pantauan</button><?php endif;?></div><?php if($canManage):?><form class="panel-card form-panel" id="obsForm" method="post" hidden><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_observation"><div class="form-grid"><label>Pasien<select name="patient_id"><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Tekanan darah<input name="blood_pressure" placeholder="120/80"></label><label>Suhu (°C)<input type="number" step=".1" name="temperature"></label><label>Ukuran luka (cm)<input type="number" step=".1" name="wound_size"></label><label>Keluhan<input name="complaint"></label><label>Catatan<textarea name="notes"></textarea></label></div><button class="btn btn-primary">Simpan pantauan</button></form><?php endif;?><div class="panel-card table-card"><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pasien</th><th>Tekanan darah</th><th>Suhu</th><th>Luka</th><th>Keluhan</th></tr></thead><tbody><?php foreach($pdo->query('SELECT o.*,p.name patient FROM observations o JOIN patients p ON p.id=o.patient_id ORDER BY o.recorded_at DESC') as $o):?><tr><td><?=e($o['recorded_at'])?></td><td><?=e($o['patient'])?></td><td><?=e($o['blood_pressure'] ?: '—')?></td><td><?=e($o['temperature'] ?: '—')?></td><td><?=e($o['wound_size'] ?: '—')?></td><td><?=e($o['complaint'] ?: '—')?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($page==='messages'):?>
<div class="page-intro"><div><h1>Pesan perawatan</h1><p>Komunikasi keluarga dan tim perawat.</p></div></div><div class="two-col"><article class="panel-card"><div class="panel-head"><h3>Pesan terbaru</h3></div><?php foreach($pdo->query('SELECT m.*,u.name sender,p.name patient FROM messages m JOIN users u ON u.id=m.sender_id JOIN patients p ON p.id=m.patient_id ORDER BY m.created_at DESC LIMIT 50') as $m):?><div class="message-item"><b><?=e($m['sender'])?></b><span class="tag"><?=e($m['patient'])?></span><p><?=e($m['message'])?></p><small><?=e($m['created_at'])?></small></div><?php endforeach;?></article><form class="panel-card form-panel" method="post"><h3>Kirim pesan</h3><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_message"><label>Pasien<select name="patient_id"><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Pesan<textarea name="message" required></textarea></label><button class="btn btn-primary">Kirim pesan</button></form></div>
<?php elseif($page==='reports'):?>
<div class="page-intro"><div><h1>Laporan harian</h1><p>Dokumentasi kondisi, tindakan, dan respons pasien.</p></div><?php if($canManage):?><button class="btn btn-primary" onclick="document.getElementById('reportForm').hidden=false">＋ Buat laporan</button><?php endif;?></div><?php if($canManage):?><form class="panel-card form-panel" id="reportForm" method="post" hidden><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_report"><div class="form-grid"><label>Pasien<select name="patient_id"><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Tanggal<input type="date" name="report_date" value="<?=date('Y-m-d')?>"></label><label class="span-2">Ringkasan<textarea name="summary" required></textarea></label><label class="span-2">Tindakan<textarea name="actions_taken"></textarea></label><label class="span-2">Respons pasien<textarea name="response"></textarea></label></div><button class="btn btn-primary">Simpan laporan</button></form><?php endif;?><div class="panel-card table-card"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pasien</th><th>Penulis</th><th>Ringkasan</th><th>Tindakan</th><th>Respons</th></tr></thead><tbody><?php foreach($pdo->query('SELECT r.*,p.name patient,u.name author FROM reports r JOIN patients p ON p.id=r.patient_id JOIN users u ON u.id=r.author_id ORDER BY report_date DESC') as $r):?><tr><td><?=e($r['report_date'])?></td><td><?=e($r['patient'])?></td><td><?=e($r['author'])?></td><td><?=e($r['summary'])?></td><td><?=e($r['actions_taken'])?></td><td><?=e($r['response'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php endif;?><footer class="footer">© <?=date('Y')?> RawatBersama <span>Informasi ini merupakan dokumentasi perawatan, bukan pengganti keputusan klinis.</span></footer></section></main></div><script src="assets/app.js"></script></body></html>